{
  "description": "The creature is shown in right-facing profile standing on a small patch of sparse grass against a plain light background. It has the overall body shape, head, and limbs of a horse but is almost entirely armored with overlapping pangolin-like scales. The body is stout and horse-proportioned with a long neck, deep chest, and rounded hindquarters. The head is dark brown and horse-like with an elongated muzzle, large nostril, dark eye, and upright ears, mostly covered in short hair except for a cap of scales on the forehead. From the top of the neck along the back, sides, hindquarters, upper legs, and the full length of the long tapering tail, the skin is covered in dense, large, overlapping rounded scales in shades of dark brown and tan with lighter edges. The lower portions of the four legs below the scale coverage show dark brown hair and end in hooves, and the underbelly and chest show lighter tan hair between the scaled areas.",
  "parts": [
    {
      "part": "head",
      "looks_like": "horse-like head with elongated muzzle, large dark nostril, dark eye with eyelid, and short whiskers around the mouth and chin; dark brown hair-covered skin except for scaled forehead",
      "where": "at the right end of the neck, facing right in profile"
    },
    {
      "part": "ears",
      "looks_like": "two pointed, upright horse ears with dark brown outer hair and lighter inner surface",
      "where": "on top of the head, one slightly in front of the other in profile view"
    },
    {
      "part": "mane",
      "looks_like": "no hair mane visible; the dorsal crest of the neck where a mane would be is covered in overlapping large rounded scales that continue from the neck onto the back",
      "where": "along the top edge of the neck from behind the ears to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy horse-like legs; upper portions from shoulder and thigh down to about the knee/hock are covered in overlapping scales, lower portions are covered in short dark brown hair with lighter hair near the fetlock",
      "where": "two forelegs under the chest and two hindlegs under the hindquarters, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four solid dark brown hooves with a slightly worn texture, each with a ring of light and dark hair immediately above",
      "where": "at the bottom ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a rounded tip, fully covered on all visible surfaces with overlapping rounded scales matching the body, hanging nearly vertically",
      "where": "extending down and slightly outward from the rear of the hindquarters on the left side of the image"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous plates in dark to medium brown with tan or cream-colored edges and faint concentric growth lines, arranged in diagonal rows like roof shingles",
      "where": "densely covering the dorsal neck, back, sides, hindquarters, upper forelegs and hindlegs, tail, and a cap on the forehead between and in front of the ears; absent on the face, lower legs, and underbelly"
    },
    {
      "part": "plates",
      "looks_like": "same as scales - large overlapping rounded bony plates with brown centers and lighter margins",
      "where": "covering the neck, torso, upper limbs, tail and forehead cap as described for scales"
    }
  ],
  "attached_objects": [],
  "animals": [
    "horse",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
